void encode_to_stream_VkRenderPassBeginInfo(VkStructureType rootType,
                                           const VkRenderPassBeginInfo* forMarshaling,
                                           uint8_t** ptr) {
    (void)rootType;
    memcpy(*ptr, (VkStructureType*)&forMarshaling->sType, sizeof(VkStructureType));
    *ptr += sizeof(VkStructureType);
    if (rootType == VK_STRUCTURE_TYPE_MAX_ENUM) {
        rootType = forMarshaling->sType;
    }
    encode_to_stream_extension_struct(rootType, forMarshaling->pNext, ptr);
    uint64_t cgen_var_0;
    *&cgen_var_0 = (uint64_t)forMarshaling->renderPass;
    memcpy(*ptr, (uint64_t*)&cgen_var_0, 1 * 8);
    *ptr += 1 * 8;
    uint64_t cgen_var_1;
    *&cgen_var_1 = (uint64_t)forMarshaling->framebuffer;
    memcpy(*ptr, (uint64_t*)&cgen_var_1, 1 * 8);
    *ptr += 1 * 8;
    encode_to_stream_VkRect2D(rootType, (VkRect2D*)(&forMarshaling->renderArea), ptr);
    memcpy(*ptr, (uint32_t*)&forMarshaling->clearValueCount, sizeof(uint32_t));
    *ptr += sizeof(uint32_t);
    // WARNING PTR CHECK
    uint64_t cgen_var_2 = (uint64_t)(uintptr_t)forMarshaling->pClearValues;
    memcpy((*ptr), &cgen_var_2, 8);
    *ptr += 8;
    if (forMarshaling->pClearValues) {
        for (uint32_t i = 0; i < (uint32_t)forMarshaling->clearValueCount; ++i) {
            encode_to_stream_VkClearValue(
                rootType, (const VkClearValue*)(forMarshaling->pClearValues + i), ptr);
        }
    }
}

void encode_to_stream_VkPresentInfoKHR(VkStructureType rootType,
                                      const VkPresentInfoKHR* forMarshaling,
                                      uint8_t** ptr) {
    (void)rootType;
    memcpy(*ptr, (VkStructureType*)&forMarshaling->sType, sizeof(VkStructureType));
    *ptr += sizeof(VkStructureType);
    if (rootType == VK_STRUCTURE_TYPE_MAX_ENUM) {
        rootType = forMarshaling->sType;
    }
    encode_to_stream_extension_struct(rootType, forMarshaling->pNext, ptr);
    
    memcpy(*ptr, (uint32_t*)&forMarshaling->waitSemaphoreCount, sizeof(uint32_t));
    *ptr += sizeof(uint32_t);
    if (forMarshaling->waitSemaphoreCount) {
        uint8_t* semaphore_ptr = (uint8_t*)(*ptr);
        if (forMarshaling->pWaitSemaphores) {
            for (uint32_t k = 0; k < forMarshaling->waitSemaphoreCount; ++k) {
                uint64_t tmpval = (uint64_t)forMarshaling->pWaitSemaphores[k];
                memcpy(semaphore_ptr + k * 8, &tmpval, sizeof(uint64_t));
            }
        }
        *ptr += 8 * forMarshaling->waitSemaphoreCount;
    }
    
    memcpy(*ptr, (uint32_t*)&forMarshaling->swapchainCount, sizeof(uint32_t));
    *ptr += sizeof(uint32_t);
    if (forMarshaling->swapchainCount) {
        uint8_t* swapchain_ptr = (uint8_t*)(*ptr);
        if (forMarshaling->pSwapchains) {
            for (uint32_t k = 0; k < forMarshaling->swapchainCount; ++k) {
                uint64_t tmpval = (uint64_t)forMarshaling->pSwapchains[k];
                memcpy(swapchain_ptr + k * 8, &tmpval, sizeof(uint64_t));
            }
        }
        *ptr += 8 * forMarshaling->swapchainCount;
        
        if (forMarshaling->pImageIndices) {
            memcpy(*ptr, forMarshaling->pImageIndices, 
                   forMarshaling->swapchainCount * sizeof(uint32_t));
        }
        *ptr += forMarshaling->swapchainCount * sizeof(uint32_t);
    }
    
    if (forMarshaling->pResults) {
        memcpy(*ptr, forMarshaling->pResults, 
               forMarshaling->swapchainCount * sizeof(VkResult));
        *ptr += forMarshaling->swapchainCount * sizeof(VkResult);
    }
}


